// IPGen スーパーセット (x11_y17_om19_pi45) 用: 構成メモリ CONF_FF チェーン + FPGA_CORE（先輩の FPGA_CORE.v と同じ形）
// EFPGA_CORE/ 配下の全 .v と一緒に読み、top=FPGA_CORE で合成する
module CONF_FF(CONF_OUT, CF, CONF_RESETL, CONF_MODE, CONF_IN, CONF_E, CONF_CLK);
   input CONF_RESETL; input CONF_MODE; input CONF_IN; input CONF_E; input CONF_CLK;
   output CONF_OUT; output CF;
   reg Tmp;
   always @(posedge CONF_CLK or negedge CONF_RESETL)
     if (~CONF_RESETL) Tmp <= 1'b0;
     else if (CONF_MODE) Tmp <= CONF_IN;
     else Tmp <= Tmp;
   assign CF = (CONF_E & Tmp);
   assign CONF_OUT = Tmp;
endmodule
